/**
 * Liste officielle des entités DXCC (~340 entités).
 * Source : ARRL DXCC List (mise à jour 2024).
 * Chaque entité a : code (préfixe principal), nom, préfixes associés, continent, CQ zone, ITU zone,
 * et isoCode (ISO 3166-1 alpha-2) pour l'affichage du drapeau emoji.
 * Pour les territoires sans souveraineté propre, on utilise le code du pays administrant.
 */
export interface DxccEntity {
  /** Préfixe principal (ex: "JA", "W", "F") */
  code: string;
  /** Nom officiel de l'entité */
  name: string;
  /** Continent (EU, NA, SA, AF, AS, OC, AN) */
  continent: string;
  /** Zone CQ */
  cqZone: number;
  /** Zone ITU */
  ituZone: number;
  /** Préfixes d'indicatifs associés (pour matching) */
  prefixes: string[];
  /** Code ISO 3166-1 alpha-2 pour le drapeau emoji (null si pas de drapeau applicable) */
  isoCode?: string;
}

