/**
 * Trouve l'entité DXCC correspondant à un indicatif.
 * Retourne null si non trouvé.
 */
export function findDxccByCallsign(callsign: string): DxccEntity | null {
  const call = callsign.toUpperCase().trim();
  // Chercher le préfixe le plus long qui correspond
  let best: DxccEntity | null = null;
  let bestLen = 0;
  for (const entity of DXCC_ENTITIES) {
    for (const prefix of entity.prefixes) {
      if (call.startsWith(prefix) && prefix.length > bestLen) {
        best = entity;
        bestLen = prefix.length;
      }
    }
  }
  return best;
}

/**
 * Trouve l'entité DXCC par nom de pays (insensible à la casse, correspondance partielle).
 * Utile comme fallback pour les QSO importés qui ont un champ COUNTRY dans l'ADIF.
 */
export function findDxccByCountryName(countryName: string): DxccEntity | null {
  if (!countryName) return null;
  const needle = countryName.toLowerCase().trim();
  // Correspondance exacte d'abord
  for (const entity of DXCC_ENTITIES) {
    if (entity.name.toLowerCase() === needle) return entity;
  }
  // Correspondance partielle (le nom stocké contient le nom de l'entité ou vice-versa)
  for (const entity of DXCC_ENTITIES) {
    const ename = entity.name.toLowerCase();
    if (needle.includes(ename) || ename.includes(needle)) return entity;
  }
  return null;
}
